function recomputeLevels(seam: ISqlSeam): Observable<void> {
  const sql = `DELETE FROM "__host_demand_span_scan";
INSERT OR IGNORE INTO "__host_demand_span_scan" ("identity_digest", "witness_digest", "file_digest", "query_digest") SELECT ('identity|span_scan' || '|' || 'file_digest' || ':' || 'text' || '=' || b0."file_digest" || '|' || 'query_digest' || ':' || 'text' || '=' || b1."query_digest"), ('witness|span_scan' || '|' || 'file_digest' || ':' || 'text' || '=' || b0."file_digest" || '|' || 'query_digest' || ':' || 'text' || '=' || b1."query_digest"), b0."file_digest", b1."query_digest" FROM "file" b0, "query_value" b1;
DELETE FROM "span_line";
INSERT OR IGNORE INTO "span_line" ("file", "line", "text") SELECT b0."file", b2."line", b2."text" FROM "file" b0, "query_value" b1, "__host_response_span_scan" b2 WHERE b2."file_digest" = b0."file_digest" AND b2."query_digest" = b1."query_digest" AND b2."witness_digest" = ('witness|span_scan' || '|' || 'file_digest' || ':' || 'text' || '=' || b0."file_digest" || '|' || 'query_digest' || ':' || 'text' || '=' || b1."query_digest")`;
  return seam.runner.executeMultiple(seam.db, sql);
}

function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const __host_demand_span_scan = multisetDiff(before.__host_demand_span_scan, after.__host_demand_span_scan);
  const __host_response_span_scan = multisetDiff(before.__host_response_span_scan, after.__host_response_span_scan);
  const file = multisetDiff(before.file, after.file);
  const query_value = multisetDiff(before.query_value, after.query_value);
  const span_line = multisetDiff(before.span_line, after.span_line);
  return {
    rels: [
      { rel: "__host_demand_span_scan", add: __host_demand_span_scan.add, del: __host_demand_span_scan.del },
      { rel: "__host_response_span_scan", add: __host_response_span_scan.add, del: __host_response_span_scan.del },
      { rel: "file", add: file.add, del: file.del },
      { rel: "query_value", add: query_value.add, del: query_value.del },
      { rel: "span_line", add: span_line.add, del: span_line.del },
    ],
    carryPending: false,
  };
}

function runNaiveTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // extraction_fork_span_line: no edge rules -- absorb arrivals, recompute levels, diff.
}

const INCREMENTAL_PROGRAM_SAFE = true;
const RECONCILE_EVERY_TICK = false;
const EMITTER_MODE = process.env.SPREFA_TSV2_EMITTER_MODE === "naive" ? "naive" : "incremental";

function runIncrementalTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return IncrementalRuntime.prepareTick(seam, INCREMENTAL_RELATIONS).pipe(
    concatMap(() => IncrementalRuntime.applyArrivals(seam, arrivals, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyLevelsBeforeEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS)),
    concatMap(() => IncrementalRuntime.applyEdges(seam, INCREMENTAL_EDGE_STATEMENTS, INCREMENTAL_RELATIONS)),
    concatMap(() => of(undefined)),
    concatMap(() => of(undefined)),
    concatMap(() => IncrementalRuntime.recomputeLevelsAfterEdges(seam, INCREMENTAL_LEVEL_STATEMENTS, INCREMENTAL_RELATIONS, RECONCILE_EVERY_TICK)),
    concatMap(() => IncrementalRuntime.readBoundary(seam, INCREMENTAL_RELATIONS)),
    concatMap((rels) => IncrementalRuntime.promoteFrontiers(seam, INCREMENTAL_RELATIONS).pipe(
      map((carryPending): ITickDeltas => ({ rels, carryPending })),
    )),
  );
}

function runTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  arrivals = validateArrivals(arrivals);
  if (EMITTER_MODE === "naive" || !INCREMENTAL_PROGRAM_SAFE) {
    return runNaiveTick(seam, arrivals);
  }
  return runIncrementalTick(seam, arrivals);
}

export const incrementalPlan: IIncrementalProgramPlan = {
  safe: INCREMENTAL_PROGRAM_SAFE,
  reconcileEveryTick: RECONCILE_EVERY_TICK,
  retractionGuard: "plain-count-acyclic",
  relations: INCREMENTAL_RELATIONS,
  edges: INCREMENTAL_EDGE_STATEMENTS,
  levels: INCREMENTAL_LEVEL_STATEMENTS,
};

export const program: IGenProgramWithBoot = {
  name: "extraction_fork_span_line",
  ddl,
  relColumns,
  relColumnTypes,
  arrivalTargets,
  boot,
  finalSelect,
  hostPlans,
  bindPlans,
  queryPlans,
  unsupportedExecution,
  tick: runTick,
};
